def f(g):
    h,w=len(g),len(g[0]); o=[r[:] for r in g]
    bars=[]
    for r in range(h):
        cols=defaultdict(list)
        for c in range(w):
            if g[r][c]: cols[g[r][c]].append(c)
        for col,cs in cols.items():
            if len(cs)>=2: bars.append((r,col,min(cs),max(cs)))
    barrows={b[0] for b in bars}
    for c in range(w):
        vs=[r for r in range(h) if g[r][c] and r not in barrows]
        if not vs: continue
        top=min(vs); vcol=g[top][c]
        for r in range(h):
            if g[r][c]!=0 and r not in barrows:
                o[r][c]=g[r][c]; continue  # vertical cells keep color
            below=[b for b in bars if b[0]>=r and b[2]<=c<=b[3]]
            if below:
                b=min(below,key=lambda b:b[0]); o[r][c]=b[1]
            elif r>=top or (r<top and not below):
                o[r][c]=vcol
            # else stays 0
    return o
